        ("○×", 2, "「プラグマティズム（実用主義）」とは、概念や真理の意味を、現実の行動や実践的な結果・有効性によって捉える哲学である。", True, "パース、ジェイムズ、デューイらが発展させた、観念の正しさを実際の結果や働きから検証する思想である。"),
        ("○×", 2, "「功利主義」は、個人の内面的な義務や良心のみを基準とし、行為がもたらす結果の幸不幸は一切考慮しない思想である。", False, "結果を重視せず義務を重んじるのはカントの義務論であり、功利主義は「最大多数の最大幸福」という結果を重視する。"),
        ("○×", 1, "「対句」とは、意味や語調の対応した二つの語句・文を並べて表現にリズムと強調を与える修辞法である。", True, "「山は高く、海は深い」のように構造を対称にして並べる技法で、リズムや対比効果を高める。"),
        ("○×", 2, "「マックス・ウェーバー」が論じた「脱魔術化（世界の脱呪術化）」とは、科学や合理化の進展により世界から神秘的・呪術的な意味が失われる過程を指す。", True, "近代化に伴って自然や社会が合理的に計算・説明可能となり、神秘性が薄れていく現象を指す重要概念である。"),
        ("○×", 2, "「イデオロギー」とは、個人のその場限りの気分や一時的な好みだけを指す心理学用語である。", False, "イデオロギーは、歴史的・社会的な立場や階級に結びついた体系的な思想・政治的信条・観念形態を指す。"),
