        ("○×", 2, "「マジョリティ」とは社会の中で数や力の面で多数派を占める集団、「マイノリティ」とは少数派を指す。", True, "多数派（マジョリティ）の常識が少数派（マイノリティ）を見えにくくする構造が評論ではよく問われる。"),
        ("○×", 3, "「ア・プリオリ」とは、個人の経験を通じて後から獲得された知識や性質を意味する言葉である。", False, "ア・プリオリ（先天的・先験的）は経験に先立って備わっていることを指し、経験に基づくことは「ア・ポステリオリ」という。"),
