        (2, "矜持", "自分の能力や信念に対する誇りやプライド", "読みは「きょうじ」。「仕事への矜持を保つ」のように用いる。"),
        (2, "逡巡", "決心がつかず、ためらってぐずぐずすること", "読みは「しゅんじゅん」。進みかけては立ち止まる様子から来ている。"),
        (2, "齟齬", "互いの意見や計画などが食い違ってかみ合わないこと", "読みは「そご」。もともとは上下の歯がかみ合わないことを表した。"),
