        (1, "再読文字「将」を訓読するとき、1度目と2度目を合わせてどのように読むか（「〜」を挟んでひらがなで答えよ）。", "まさに〜んとす", ["まさに～んとす"], "「将」は1度目に「まさに」と読み、返って2度目に「んとす（むとす）」と読む（今にも〜しようとする）。"),
        (2, "再読文字「当」「応」を訓読するとき、1度目と2度目を合わせてどのように読むか（「〜」を挟んでひらがなで答えよ）。", "まさに〜べし", ["まさに～べし"], "「当」「応」は1度目に「まさに」と読み、2度目に「べし」と読んで「当然〜すべきだ」の意を表す。"),
