        (2, "再読文字「猶」を訓読するとき、1度目と2度目を合わせてどのように読むか（「〜」を挟んでひらがなで答えよ）。", "なお〜のごとし", ["なお～のごとし", "なほ〜のごとし", "なほ～のごとし"], "「猶」は「なお（なほ）〜のごとし」と読み、「ちょうど〜のようだ」という比況を表す。"),
