        ("記述", 1, "森鷗外『舞姫』で、ドイツへ留学した主人公の日本の青年官僚の氏名を漢字5字（姓・名とも）で答えよ。", "太田豊太郎", ["おおたとよたろう", "豊太郎"], "ベルリンで踊り子エリスと恋に落ち、公的な立身と私的な愛の間で苦悩する青年・太田豊太郎が描かれる。"),
        ("記述", 2, "夏目漱石の『三四郎』『それから』に続く前期三部作の最終作のタイトルを漢字1字で答えよ。", "門", ["もん"], "前期三部作は『三四郎』（1908）→『それから』（1909）→『門』（1910）の3作品である。"),
        ("記述", 2, "夏目漱石がロンドン留学や執筆活動と並行して追求した思想で、他人の評価に振り回されず自分の基準で生きる態度を漢字4字で何というか。", "自己本位", ["じこほんい"], "講演「私の個人主義」などで漱石が語ったキーワードが「自己本位」である。"),
        ("記述", 1, "志賀直哉『城の崎にて』で、主人公が散策中に生と死を見つめる契機となった三つの生き物は「蜂」「いもり」ともう一つは何か（漢字1字で答えよ）。", "鼠", ["ねずみ", "ネズミ"], "『城の崎にて』では死んだ「蜂」、首に串が刺さって川に投げ込まれた「鼠」、石を投げて偶然殺してしまった「蠑螈（いもり）」の三つの生と死が描かれる。"),
        ("記述", 2, "志賀直哉『城の崎にて』で、主人公が何気なく投げた石が当たって死なせてしまった小さな生き物は何か（ひらがな3字で答えよ）。", "いもり", ["イモリ", "蠑螈"], "小川の石の上にいた「いもり（蠑螈）」に脅かすつもりで投げた石が当たり、偶然の死を目の当たりにして生と死を静かに見つめる。"),
        ("記述", 2, "梶井基次郎の短編『檸檬』で、主人公が「得体の知れない不吉な塊」に圧迫されながら、鮮やかなレモンを爆弾に見立てて洋画集の山の上に置いて立ち去った実在の書店はどこか（漢字2字）。", "丸善", ["まるぜん"], "京都の老舗洋書店・丸善の店内で、貧困や病への焦燥を鮮やかなレモンの想像力によって一時的に打ち払う名場面が描かれる。"),
        ("記述", 2, "太宰治『走れメロス』で、メロスが妹の結婚式のために3日間の猶予をもらう間、シラクスの王のもとに身代わりとして残った親友の名前は何か。", "セリヌンティウス", ["せりぬんてぃうす"], "石工のセリヌンティウスは一言の疑いもなくメロスの身代わりを引き受け、二人の信実が暴君ディオニスの心を動かす。"),
        ("記述", 2, "夏目漱石が『吾輩は猫である』を発表したきっかけとなった、正岡子規の写生文を受け継ぎ高浜虚子が編集した俳句雑誌は何というか（カタカナ5字）。", "ホトトギス", ["ほととぎす"], "俳誌『ホトトギス』に『吾輩は猫である』が連載され、夏目漱石は一躍小説家として脚光を浴びた。"),
        ("記述", 2, "明治期に尾崎紅葉を中心に結成され、『我楽多文庫』を機関誌として江戸戯作の流れを汲む作品を生んだ文学結社を何というか（漢字3字）。", "硯友社", ["けんゆうしゃ"], "尾崎紅葉『金色夜叉』や泉鏡花らが関係した明治前半の代表的な文学団体である。"),
        ("記述", 3, "『金色夜叉』の作者であり、長編小説『多情多恨』で近代小説の「〜である」調の文体を洗練・定着させた明治の作家は誰か。", "尾崎紅葉", ["おざきこうよう"], "二葉亭四迷の「だ」調、山田美妙の「です」調に対し、尾崎紅葉は『多情多恨』で「である」調を洗練させ近代小説の文体に大きく寄与した。"),
        ("記述", 2, "明治20年代に北村透谷・島崎藤村らが創刊し、初期浪漫主義の拠点となった文芸雑誌の名称は何か（漢字3字）。", "文学界", ["ぶんがくかい"], "1893年に創刊された『文学界』は北村透谷の思想や樋口一葉『たけくらべ』などを掲載した重要雑誌である。"),
        ("記述", 2, "明治期の雑誌『明星』を主宰し、与謝野晶子らとともに浪漫主義短歌を牽引した歌人は誰か。", "与謝野鉄幹", ["与謝野寛", "よさのてっかん", "よさのひろし"], "与謝野鉄幹（寛）が新詩社を結成して『明星』を創刊し、妻となった与謝野晶子『みだれ髪』など浪漫派の才能を育てた。"),
        ("○×", 1, "明治時代初期には、二葉亭四迷の『浮雲』などを通じて、話し言葉に近い文体で小説を書く「言文一致運動」が進められた。", True, "文語体から脱却し、現代の小説・散文につながる口語文体が明治から大正にかけて定着した。"),
        ("○×", 1, "夏目漱石の『坊っちゃん』は、江戸っ子気質の主人公が四国の松山（作中では言及される地方の中学校）へ数学教師として赴任する物語である。", True, "不正や卑怯を嫌う青年教師「坊っちゃん」が、狸・赤シャツ・野だいこ・うらなり・山嵐らと関わる痛快な小説である。"),
        ("○×", 2, "森鷗外の『舞姫』は、全編が現代と同じ「〜だ・〜である」の口語体で書かれている。", False, "『舞姫』は雅文体（文語体の一種、「〜ぬ」「〜けり」「〜なり」など）で書かれている。"),
        ("○×", 1, "芥川龍之介は、夏目漱石からその才能を高く評価された門下生の一人である。", True, "漱石が『鼻』を絶賛する手紙を芥川に送ったことは日本近代文学史上有名な逸話である。"),
        ("○×", 2, "中島敦の『山月記』は、作者がオリジナルで一から創作した現代の東京を舞台にした物語である。", False, "唐代の伝奇小説『人虎伝』を原典として翻案・再構成した作品である。"),
        ("○×", 2, "『こころ』の「K」は、精進（道）を貫くストイックな性格であったが、「お嬢さん」への恋心に悩むようになった。", True, "先生とKが下宿先のお嬢さんを巡って葛藤し、先生の裏切りがKの自死につながる悲劇が描かれる。"),
        ("○×", 1, "太宰治の『走れメロス』は、ドイツの詩人シラーの詩『人質』などをもとにした作品である。", True, "シラーの譚詩『人質』や古代ギリシアの伝説を下敷きに、太宰独自の人間観で再構築している。"),
        ("○×", 2, "「私小説」とは、登場人物の心理を客観的に描くため、作者本人の体験や私生活とは一切無関係な架空の冒険だけを書く小説のことである。", False, "私小説は作者自身の体験や内面告白を事実とほぼ重ね合わせて一人称または三人称で描く日本近代特有の小説形式である。"),
        ("○×", 2, "樋口一葉の『たけくらべ』は、言文一致の口語体で書かれている。", False, "『たけくらべ』は井原西鶴の影響を受けた流麗な雅俗折衷体（文語基調）で書かれている。"),
        ("○×", 1, "川端康成は1968年に日本人として初めてノーベル文学賞を受賞した。", True, "『雪国』『千羽鶴』『古都』などの作品が高く評価され、受賞記念講演『美しい日本の私』も著名である。"),
        ("○×", 2, "宮沢賢治の『銀河鉄道の夜』の主人公の名前はジョバンニとカムパネルラである。", True, "孤独な少年ジョバンニが親友カムパネルラとともに銀河鉄道の旅をする幻想的童話である。"),
        ("○×", 2, "夏目漱石の『吾輩は猫である』の語り手「吾輩」は、飼い主である英語教師・珍野苦沙弥の家に住み着いた名無しの猫である。", True, "「吾輩は猫である。名前はまだ無い。」から始まり、猫の目線から人間社会を風刺的に観察する。"),
