        ("選択", 2, "グループで新しいアイデアを数多く出し合う「ブレーンストーミング」の4原則に含まれないものはどれか。", "発言されたアイデアをその場ですぐに厳しく批判・却下する", ["批判厳禁（評価を後回しにする）", "質より量（とにかく多くの案を出す）", "自由奔放（突飛なアイデアも歓迎する）"], "ブレーンストーミングでは「批判厳禁」「自由奔放」「質より量」「結合改善（他人の案に便乗）」の4原則で発散的思考を促す。"),
