        ("記述", 2, "小説の結末をあえて明確に言い切らず、読者の解釈に余地を残して終える終わり方を「（　）れた結末」（オープンエンディング）という（空欄を2文字で答えよ）。", "開か", ["開かれた", "開かれた結末", "オープンエンディング"], "「大団円」のようにすべてが丸く収まる「閉じた結末」と対照的に、現代小説では読者に思考を委ねる「開かれた結末」も多い。"),
        ("記述", 3, "「物語の中で主人公と対立する敵対者・障害となる人物（例：主人公＝プロタゴニストに対する敵役）」を文学用語のカタカナで何というか。", "アンタゴニスト", ["あんたごにすと"], "主人公（プロタゴニスト）の目標達成を阻む存在（悪役だけでなく環境や内面の葛藤を含む）をアンタゴニストという。"),
