        ("○×", 1, "小川洋子『博士の愛した数式』は、数字の美しさや友情数・素数などの数学の概念が人間関係の絆を象徴する役割を果たしている。", True, "記憶障害を抱えた元数学者と家政婦・ルート（少年）の交流が数式の象徴性とともに温かく描かれる。"),
