        ("記述", 2, "和歌で、古く有名な先人の歌（本歌）の表現や発想を意図的に取り入れて、新しい意味や奥行きを重ねる技法を漢字4字で何というか。", "本歌取り", ["ほんかどり"], "特に『新古今和歌集』の時代に藤原定家らによって高度に洗練された技法。"),
