        ("記述", 2, "現代の口語詩で、高村光太郎が最愛の妻への深い愛と葛藤、そして自然の中での彼女の姿を詠んだ詩集の題名は何か（漢字3字＋「抄」）。", "智恵子抄", ["ちえこしょう"], "「あどけない話」「レモン哀歌」などが収められている。"),
