        ("記述", 3, "昭和期の詩人で、カエルを題材にした生命感あふれる詩（『第百階級』など）を多く書き、「ゐ」「るり」「ごびらっふ」など独自の擬音表現で知られる詩人は誰か。", "草野心平", ["くさのしんぺい"], "「天」「富士山」「蛙」を生涯のモチーフとし、歴程派の中心として活躍した。"),
        ("記述", 2, "短歌の革新や近代短歌において、「若山牧水」の代表的な作風として、旅と酒と自然への愛惜を詠んだ有名な歌「白鳥は（　）しからずや空の青海のあをにも染まずただよふ」の空欄を漢字1字で答えよ。", "哀", ["かな", "悲"], "「白鳥は哀しからずや」で有名な自然への深い哀愁を帯びた歌である。"),
