        ("○×", 1, "俳句の「五・七・五」のうち、どこかに必ず「句切れ」が1箇所しか許されないという規則がある。", False, "切れ字のない一気呵成の句や、二箇所で切れる句もあり、一箇所とは限らない（ただし切れ字を多用しすぎると散漫になるため1つに絞ることが多い）。"),
        ("○×", 2, "萩原朔太郎の『月に吠える』は、文語と七五調を厳格に守った「文語定型詩」の代表作である。", False, "『月に吠える』は、内面の不安や感覚を豊かな音楽性をもった口語自由詩で表現した画期的詩集である。"),
