        ("○×", 2, "正岡子規は、松尾芭蕉の句を無条件に絶対視するのではなく、『俳諧大要』や『歌よみに与ふる書』などで与謝蕪村の再評価や『古今集』批判を行った。", True, "写生の観点から『古今集』の機知よりも『万葉集』の率直さ、芭蕉だけでなく蕪村の客観的絵画性を高く評価した。"),
        ("○×", 2, "俳句において、一つの句の中に「桜」と「雪」のように異なる季節の季語を2つ以上並べて入れることは「季重なり」と呼ばれ、初心者は避けるのがよいとされる。", True, "焦点を一つの季節・感動に絞るため、原則として「一旬一季語」が基本とされる（意図的に使う熟練の例外はある）。"),
        ("○×", 1, "与謝野晶子の代表歌「君死にたまふことなかれ」は、日露戦争に出征した弟への切実な思いを歌った詩である。", True, "1904年に『明星』に発表され、個人の生命と家族愛の尊さを率直に詠んで大きな反響を呼んだ長詩（歌ではなく詩）である。"),
        ("○×", 2, "「詩の散文訳（意味の要約）」をすると、元の詩がもっていた改行・連の空白・音のリズムによる効果がそのまま失われずに保存される。", False, "詩は言葉の意味だけでなく音韻・リズム・視覚的配置（行分けや余白）が一体となって表現を生むため、散文に直すと表現効果が失われる。"),
        ("○×", 2, "『万葉集』の歌風は素朴で力強く率直な「ますらをぶり」、『古今和歌集』の歌風は優美で繊細な「たをやめぶり」と評されることが多い。", True, "賀茂真淵らが指摘した伝統的な歌風の対比である。"),
