        ("選択", 2, "随筆というジャンルにおいて、著者が自分自身の失敗談や情けない一面を隠さずに書くことで読者にもたらされる効果はどれか。", "書き手への親近感が生まれ、それに続く人生への考察に人間的な説得力が出る", ["文章全体の信頼性が失われて誰も読まなくなる", "論説文としての法的効力が発生する", "すべての登場人物が架空であることが証明される"], "完璧な聖人君子としてではなく等身大の「私」として語ることで、読者の共感と自己投影を誘う。"),
        ("選択", 3, "小林秀雄『無常といふ事』において、歴史や古典を「解釈しすぎて理屈で割り切ること」を批判しつつ著者が重視した姿勢はどれか。", "作品や歴史の事実を「美しい花」のように直接その姿として感じ取り思い出すこと", ["過去の古典をすべて現代の経済学の数式に翻訳すること", "作者の血液型と星座だけで作品の価値を決めること", "古典作品を現代語に直す際に作者の感情をすべて削除すること"], "近代批評を確立した小林秀雄は、安易な歴史理論よりも古典作品そのものとの直接的な出会いを重視した。"),
