        ("記述", 2, "随筆・エッセイの中で、実在した過去の出来事・記憶や旅先の風物を辿りながら思いをめぐらせる旅の文章を漢字3字で何というか。", "紀行文", ["きこうぶん", "紀行随筆", "紀行"], "『土佐日記』や芭蕉『奥の細道』、内田百閒『阿房列車』など、旅と観察・思索が結びついた随筆群。"),
        ("記述", 1, "物理学者の寺田寅彦が、東京大学教授として研究する傍らで随筆・文学作品の発表に用いたペンネーム（筆名）は何か（漢字4字）。", "吉村冬彦", ["よしむらふゆひこ", "冬彦"], "科学者としての仕事とは区別し、「吉村冬彦」の名で『冬彦集』『藪柑子集』などの名随筆を発表した。"),
        ("記述", 2, "中谷宇吉郎の随筆『雪』の中にある、雪の結晶の形から上空の気象条件が読み取れることを詩的に表現した有名な一文「雪は（　）から送られた手紙である」の空欄を漢字1字で答えよ。", "天", ["てん"], "人工雪の作成に世界で初めて成功した雪氷学者・中谷宇吉郎の、科学と詩情が結びついた名言である。"),
