        ("記述", 2, "『思考の整理学』を著し、「グライダー人間」と「飛行機人間」の比喩で自力で思考を飛ばす大切さを説いた英文学者・エッセイストは誰か。", "外山滋比古", ["とやましげひこ"], "1983年刊行の『思考の整理学』は、アイデアを「寝かせる」「発酵させる」などの比喩で知の技法を説いたロングセラー随筆。"),
        ("記述", 2, "正岡子規が病床で新聞『日本』に連載した晩年の随筆で、わずかな一滴の墨になぞらえて日々の思索や飲食の楽しみを綴った作品名は『（　）一滴』である（漢字2字で答えよ）。", "墨汁", ["ぼくじゅう", "墨汁一滴"], "正岡子規は激しい闘病生活の中で『墨汁一滴』『病牀六尺』『仰臥漫録』といった優れた随筆を遺した。"),
        ("記述", 2, "幸田文の随筆や小説（『木』『流れる』『台所のおと』など）で、彼女が文豪である父から受け継いだ鋭い観察眼と端正な文章力の背景にいる、明治の文豪である実父は誰か。", "幸田露伴", ["こうだろはん"], "『五重塔』の作者・幸田露伴の次女として厳しい躾と教育を受け、父の死後に随筆家として花開いた。"),
