        ("記述", 2, "『徒然草』第52段で、兼好が「少しのことにも、先達はあらまほしき事なり」と語った、石清水八幡宮に参拝したつもりが麓の極楽寺・高良だけを拝んで帰ってしまった人物は作中でどう呼ばれているか（8文字で答えよ）。", "仁和寺にある法師", ["仁和寺の法師", "にんなじにあるほうし", "にんなじのほうし"], "専門家に聞けばすぐ分かることを自己流で早合点してしまった失敗談から、先達（案内人・経験者）の大切さを説いた名段。"),
        ("記述", 2, "白洲正子による日本の風土・神社仏閣・伝統文化をめぐる紀行随筆の代表作で、人里離れた土地に残る古い信仰と美を訪ね歩いた作品は『（　）里』である（空欄をひらがな3字で答えよ）。", "かくれ", ["かくれ里", "隠れ里"], "『かくれ里』『十一面観音巡礼』などで、鋭い審美眼と行動力に裏打ちされた随筆世界を築いた。"),
        ("記述", 3, "「随筆」というジャンルを論じる際、厳密な体系的論文に対して断片的でありながら、筆者の個人的な「（　）」を通すことでかえって普遍的な人間性に到達すると言われる。自らの生の感覚や手触りを表す漢字2字は何か。", "実感", ["じっかん"], "抽象的な理論に偏らず、筆者の生きた「実感」に根ざして語られる点に随筆ならではの説得力がある。"),
        # ○× (16問)
        ("○×", 1, "『枕草子』の「春はあけぼの」の段では、春・夏・秋・冬それぞれの季節で最も趣深い時間帯や自然現象が対比的に描かれている。", True, "春＝あけぼの、夏＝夜、秋＝夕暮れ、冬＝つとめて（早朝）と、四季の美を研ぎ澄まされた感性で切り取っている。"),
        ("○×", 1, "『方丈記』は、鴨長明が経験した大火・辻風・飢饉・地震・福原遷都という「五大災厄」の記録から幕を開け、住まいの狭さと不安定さを語っている。", True, "都市の華やかさや権力がいかに脆いかを五大災厄の具体的描写で示し、日野山の方丈生活へと至る緊密な構成をもつ。"),
        ("○×", 2, "『徒然草』では、第1段から第243段までが一貫して一つの長編物語のように同じ主人公の冒険を描いている。", False, "各段が独立した短編エッセイのような構造をとっており、長さも1行から数ページまで多様である。"),
        ("○×", 2, "モンテーニュの『エセー』は、自分が経験したことのない空想上の宇宙旅行だけを書いたSF作品集である。", False, "「私が書いているのは私自身である」と宣言し、古今の書物と自己の内面・日常経験を徹底して省察した随筆の古典である。"),
        ("○×", 1, "寺田寅彦の随筆「天災と国防」には、「天災は忘れた頃にやってくる」という有名な警句に象徴される災害への洞察が含まれている。", True, "科学的な防災意識と歴史的教訓の継承の重要性を説いた先駆的随筆として今なお読み継がれている。"),
        ("○×", 2, "谷崎潤一郎『陰翳礼讃』は、日本の和食や日本家屋もすべて欧米風の明るい照明に全面改装すべきだという主張の本である。", False, "むしろ近代化・電化によって失われつつある「陰翳（薄暗がり）」こそ日本文化の美の基盤であることを礼賛した随筆である。"),
        ("○×", 2, "随筆の終わり方には、明確な結論を一つに絞り込んで終わるだけでなく、余韻を残す問いかけや短い情景描写で静かに閉じる手法も多く見られる。", True, "「余情」を大切にし、読者にその後の思索を委ねる結び方は随筆の大きな魅力である。"),
