        ("○×", 2, "清少納言の『枕草子』は、中宮彰子に仕えた宮廷生活の悲しみを中心に書かれている。", False, "清少納言が仕えたのは一条天皇の中宮「定子」である（紫式部が仕えたのが中宮「彰子」）。"),
