        (1, "孟子（儒家・『孟子』）", "人間の本性は善であるとする「性善説」と「四端説」、仁義による「王道」を説いた", "惻隠・羞悪・辞譲・是非の「四端」を伸ばすことで誰もが聖人になりうると考えた。"),
