        ("記述", 2, "『史記』で、荊軻（けいか）が秦王政の暗殺に向かって出発する際、国境の川のほとりで詠んだ悲壮な別れの歌「風蕭々として（　）寒し、壮士ひとたび去りて復た還らず」の空欄を漢字2字で答えよ。", "易水", ["えきすい"], "刺客・荊軻が燕の太子丹らの見送りを受けて川を渡る有名な場面。"),
