        ("記述", 2, "蘇軾（蘇東坡）が赤壁の下で舟を浮かべ、自然と人生の無常と永遠を論じた名散文（賦）の題名を漢字3字で答えよ。", "赤壁賦", ["せきへきのふ", "前赤壁賦"], "「客」の人生の儚さへの嘆きに対し、蘇軾が水と月を例に「変」と「不変」の理を説き明かす名作。"),
        ("記述", 2, "柳宗元の五言絶句『江雪』で、千山に鳥も飛ばず万径に人跡も絶えた雪の川で、ただ一人舟を浮かべて釣りをしている老人のことを詩の末尾では漢字1字で何と呼んでいるか。", "翁", ["おきな", "老翁", "蓑笠の翁"], "「孤舟蓑笠の翁、独り釣る寒江の雪」で結ばれる、孤高の精神を象徴する名詩。"),
        ("記述", 2, "漢文で「不亦〜乎」を「また〜ずや」と読むとき、その文が表す意味は疑問や否定ではなく何か（漢字2字で答えよ）。", "詠嘆", ["感嘆", "えいたん", "かんたん"], "「不亦説乎（亦た説ばしからずや）」のように「〜ではないか（なんと〜なことよ）」という強い詠嘆を表す。"),
        ("記述", 2, "漢文で「何不〜（なんぞ〜ざる）」と読む句形は、「どうして〜しないのか」という疑問を通じて相手に「〜したらどうか」と促す何の意味になるか（漢字2字で答えよ）。", "勧誘", ["かんゆう", "提案"], "「何不〜」は字面の「なぜ〜しないのか」から転じて「〜しなさいよ・〜してはどうか」という勧誘になる。"),
