        ("記述", 3, "「孟母三遷」や「断機の教え」で知られる、性善説を唱えた戦国時代の儒家の思想家は誰か（漢字2字）。", "孟子", ["もうし"], "教育環境の大切さや学業を途中で投げ出す戒めを母親の逸話とともに伝える。"),
