        ("記述", 2, "『史記』に記された、秦の重臣が趙の宝玉「和氏の璧」を奪おうとした際に、命を懸けて無傷のまま持ち帰った趙の使者の名前は誰か（漢字3字）。", "藺相如", ["りんしょうじょ"], "この故事から「完璧（璧を完うす）」という言葉が生まれ、のちに将軍・廉頗との「刎頚の交わり」の逸話でも知られる。"),
        ("記述", 2, "『論語』にある「故きを温ねて新しきを知れば、以て師と為るべし」から生まれた、昔の事柄を研究して新しい道理や見解を見いだすことを表す四字熟語は何か。", "温故知新", ["おんこちしん"], "単なる懐古ではなく、過去の知識を深く吟味して現代の課題に活かす姿勢を説く言葉。"),
