        ("○×", 2, "漢文で「常不（つねに〜ず）」とある場合は部分否定であり、「いつも〜するとは限らない」という意味になる。", False, "「不常」が部分否定（常に〜とは限らない）であり、「常不」のように副詞が否定語の前に来ると「一度も〜しない（常に〜せず）」という全部否定になる。"),
        ("○×", 2, "「与其 A、寧 B」と書いてあるとき、話し手は A と B のうち B の方を選びたいと考えている。", True, "「Aするくらいなら、むしろBの方がよい（Aせんよりは、寧ろBせよ）」とBを選択する句形。"),
        ("○×", 2, "『荘子』の「無用の用」とは、世間の基準では役立たずに見えるものほど、かえって身を保ち真に大きな働きをすることがあるという逆説的な教えである。", True, "曲がりくねって材木にならない大木が、斧で伐られずに生き残り人々に木陰を与える寓話が有名。"),
