        ("記述", 1, "ネットワークに接続される機器のLANカードやWi-Fiモジュールなどに製造時から割り当てられている、世界中で原則一意な48ビットの物理アドレスを何というか（大文字英字3字＋カタカナ4字）。", "MACアドレス", ["macアドレス"], "同一LAN内（ネットワークインタフェース層）でのフレームのやり取りにはMACアドレスが使われる。"),
        ("記述", 2, "ローカルネットワーク（家庭や学校内のLAN）で使われる「プライベートIPアドレス」を、ルータがインターネット上の「グローバルIPアドレス」に変換して通信できるようにする技術をアルファベット3字または4字で何というか。", "NAT", ["NAPT", "IPマスカレード", "ナット"], "IPv4アドレスの節約と内部ネットワークの保護に欠かせない変換機能（ポート番号も含めて複数台を1つのグローバルIPで共有するのはNAPT）。"),
        ("記述", 2, "表計算ソフトやデータベースで、大量のデータから特定の項目を組み合わせて縦横に集計・クロス集計し、多角的に傾向を把握する分析機能を「（　）テーブル」というか（カタカナ4字）。", "ピボット", ["ピボットテーブル"], "データ分析において項目軸を素早く入れ替えて集計できる強力な探索的データ分析ツールである。"),
        ("記述", 2, "国や自治体・企業などが機械判読に適したデータ形式で公開し、二次利用のルールのもとで誰でも自由に活用・再配布できるようにしたデータを「（　）データ」というか（カタカナ4字）。", "オープン", ["オープンデータ"], "防災マップ、公共交通時刻表、統計データなどをオープンデータ化することで新しいアプリや地域課題の解決が促進される。"),
        # ○× (10問)
        ("○×", 1, "電子メールを自分のパソコン側で受信し管理するプロトコル「IMAP」は、メールを原則としてサーバ上に残したまま管理するため、スマートフォンとPCの両方から同じメール状態を参照しやすい。", True, "初期のPOP3は端末にダウンロードしてサーバから消す運用が基本だったのに対し、IMAPは複数端末での同期に適している。"),
