        ("○×", 2, "同じ相関係数であっても、データの分布の形は「一直線上に並ぶ」「2つの塊に分かれている」「1つの外れ値によって見かけの相関が出ている」など様々なので、必ず散布図を描いて視覚的に確認すべきである。", True, "「アンスコムの数値例」で知られる通り、要約統計量（平均・分散・相関係数）が同じでも散布図の形状は全く異なることがある。"),
